import { readFile, writeFile, mkdir, copyFile, stat } from 'node:fs/promises';
import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import crypto from 'node:crypto';

const execFileAsync = promisify(execFile);
const requirePlaywright = createRequire(new URL('../../mastra-agents/reviewer/package.json', import.meta.url));
const { chromium } = requirePlaywright('playwright');

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '../../..');
const MARKER = Buffer.from('Julia build-phase rehearsal passed.\n');

const [CONTROL_URL, RUNNER_URL, CONTROL_USER_UNIT, OUTPUT_DIR] = process.argv.slice(2);
if (!CONTROL_URL || !RUNNER_URL || !CONTROL_USER_UNIT || !OUTPUT_DIR) {
  console.error('Usage: node ops/build-runner/proof/start.mjs CONTROL_URL RUNNER_URL CONTROL_USER_UNIT OUTPUT_DIR');
  process.exit(1);
}

const OUT = path.resolve(OUTPUT_DIR);
await mkdir(OUT, { recursive: true });
await mkdir(path.join(OUT, 'job-files'), { recursive: true });

const evidence = {
  pass: false,
  controlUrl: CONTROL_URL,
  runnerUrl: RUNNER_URL,
  controlUnit: CONTROL_USER_UNIT,
  outputDir: OUT,
  startedAt: new Date().toISOString(),
  network: { requests: [], responses: [], failed: [], console: [] },
  processIdentities: {},
  restart: {}
};
let lastJob = null;
let browser = null;

function sleep(ms) { return new Promise(resolve => setTimeout(resolve, ms)); }
function controlUrl(p = '') {
  const base = CONTROL_URL.replace(/\/+$/, '');
  if (!p) return base;
  return base + (p.startsWith('/') ? p : `/${p}`);
}
function runnerUrl(p = '') {
  const base = RUNNER_URL.replace(/\/+$/, '');
  if (!p) return base;
  return base + (p.startsWith('/') ? p : `/${p}`);
}
async function fetchJson(url, options) {
  const res = await fetch(url, options);
  if (!res.ok) throw new Error(`HTTP ${res.status} ${url}: ${await res.text()}`);
  return res.json();
}
function walk(obj, cb, p = []) {
  cb(obj, p);
  if (obj && typeof obj === 'object') {
    for (const [k, v] of Object.entries(obj)) walk(v, cb, p.concat(k));
  }
}
function findReadyCardArray(state) {
  const found = [];
  walk(state, (v, p) => {
    if (Array.isArray(v) && v.length > 0 && v.every(x => x && typeof x === 'object' && !Array.isArray(x))) {
      if (v.some(x => JSON.stringify(x).includes('JUL-232'))) found.push({ path: p, value: v });
    }
  });
  if (!found.length) return null;
  found.sort((a, b) => {
    const score = x => {
      const s = JSON.stringify(x.path).toLowerCase();
      let n = 0;
      if (s.includes('ready')) n += 5;
      if (s.includes('card')) n += 5;
      if (s.includes('build')) n -= 2;
      return n + x.value.length * 0.001;
    };
    return score(b) - score(a);
  });
  return found[0].value;
}
function findBeamOffer(state) {
  const arrays = [];
  walk(state, (v, p) => {
    if (Array.isArray(v) && v.length > 0 && v.every(x => x && typeof x === 'object' && !Array.isArray(x))) {
      if (v.some(x => /beam/i.test(JSON.stringify(x)))) arrays.push({ path: p, value: v });
    }
  });
  if (arrays.length) {
    arrays.sort((a, b) => {
      const score = x => {
        const s = JSON.stringify(x.path).toLowerCase();
        let n = 0;
        if (s.includes('model')) n += 5;
        if (s.includes('offer')) n += 5;
        if (s.includes('route')) n += 3;
        return n;
      };
      return score(b) - score(a);
    });
    const arr = arrays[0].value;
    const offer = arr.find(x => /beam/i.test(JSON.stringify(x)) && /reflection/i.test(JSON.stringify(x))) ||
      arr.find(x => /beam/i.test(JSON.stringify(x)));
    if (offer) return offer;
  }
  const objs = [];
  walk(state, (v, p) => {
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      const s = JSON.stringify(v).toLowerCase();
      if (s.includes('beam') && (v.route != null || v.modelId != null || v.model != null || v.value != null)) {
        objs.push({ path: p, value: v });
      }
    }
  });
  if (!objs.length) return null;
  objs.sort((a, b) => {
    const sa = JSON.stringify(a.value).toLowerCase();
    const sb = JSON.stringify(b.value).toLowerCase();
    return (sb.includes('reflection') ? 1 : 0) - (sa.includes('reflection') ? 1 : 0);
  });
  return objs[0].value;
}
function modelValue(offer) {
  if (offer == null) return '';
  if (typeof offer !== 'object') return String(offer);
  if (typeof offer.value === 'string') return offer.value;
  if (typeof offer.id === 'string' && offer.id.includes('::')) return offer.id;
  if (offer.route != null && offer.modelId != null) return `${offer.route}::${offer.modelId}`;
  if (offer.route != null && offer.model != null) return `${offer.route}::${offer.model}`;
  const strings = Object.values(offer).filter(v => typeof v === 'string');
  const withColon = strings.find(s => s.includes('::'));
  if (withColon) return withColon;
  return strings.join('::');
}
function savedRoles(job) { return job?.roles ?? job?.savedRoles ?? job?.saved?.roles ?? {}; }
function savedCard(job) { return job?.card ?? job?.savedCard ?? job?.saved?.card; }
function actualModel(job, role) {
  const am = job?.actualModels ?? job?.actual_models ?? job?.actualModel ?? {};
  if (typeof am === 'string') return am;
  if (am && typeof am === 'object') {
    if (am[role]) return am[role];
    if (am[`${role}Model`]) return am[`${role}Model`];
    if (am[`${role}Id`]) return am[`${role}Id`];
    if (Array.isArray(am)) {
      const e = am.find(x => String(x?.role ?? x?.name ?? '').toLowerCase().includes(role));
      return e?.model ?? e?.modelId ?? e?.id ?? e?.fullId ?? e?.modelID;
    }
  }
  const cap = role.charAt(0).toUpperCase() + role.slice(1);
  if (job?.[`actual${cap}Model`]) return job[`actual${cap}Model`];
  if (job?.[`actual${cap}Id`]) return job[`actual${cap}Id`];
  return null;
}
function isTerminalSuccess(status) {
  const s = String(status ?? '').toLowerCase();
  return /ready|success|complete|done|finish/.test(s) && !/fail|error|cancel/.test(s);
}
function activeStatus(status) {
  return /^(running|started|queued|pending|in-progress|in_progress|processing)$/i.test(String(status ?? ''));
}
async function procStart(pid) {
  const raw = await readFile(`/proc/${pid}/stat`, 'utf8');
  const idx = raw.lastIndexOf(')');
  if (idx < 0) throw new Error(`cannot parse /proc/${pid}/stat`);
  const after = raw.slice(idx + 1).trim().split(/\s+/);
  if (after.length < 20) throw new Error(`short /proc/${pid}/stat`);
  return after[19];
}
async function alive(pid) {
  try { await stat(`/proc/${pid}`); return true; } catch { return false; }
}
async function waitForControlState(timeout) {
  const deadline = Date.now() + timeout;
  while (Date.now() < deadline) {
    try { await fetchJson(controlUrl('/api/state')); return; } catch {}
    await sleep(1000);
  }
  throw new Error('control state did not return after restart');
}
async function waitForJob(jobId, savedJob, timeout = 120000) {
  const deadline = Date.now() + timeout;
  while (Date.now() < deadline) {
    if (jobId) {
      try { return await fetchJson(runnerUrl(`/jobs/${jobId}`)); } catch {}
    }
    try {
      const jobs = await fetchJson(runnerUrl('/jobs'));
      const arr = Array.isArray(jobs) ? jobs : (jobs?.jobs || []);
      let found = null;
      if (jobId) found = arr.find(j => String(j?.id ?? j?.jobId ?? j?.job_id) === String(jobId));
      if (!found && savedJob) {
        found = arr.find(j => JSON.stringify(j).includes('JUL-232') && (String(j?.status || '').toLowerCase().includes('run') || String(j?.status || '').toLowerCase().includes('queue')));
      }
      if (found) return found;
    } catch {}
    await sleep(1000);
  }
  throw new Error('runner job not found');
}
async function waitForStatus(jobId, predicate, timeout, interval = 1000) {
  const deadline = Date.now() + timeout;
  let last = null;
  while (Date.now() < deadline) {
    const j = await fetchJson(runnerUrl(`/jobs/${jobId}`));
    last = j;
    if (predicate(String(j?.status ?? ''))) return j;
    const s = String(j?.status ?? '').toLowerCase();
    if (/fail|error|cancel/.test(s)) throw new Error(`job failed with status ${j?.status}`);
    await sleep(interval);
  }
  throw new Error(`timeout waiting for job status; last=${JSON.stringify(last)}`);
}
async function waitForTerminal(jobId, timeout, interval = 1000) {
  const deadline = Date.now() + timeout;
  let last = null;
  while (Date.now() < deadline) {
    const j = await fetchJson(runnerUrl(`/jobs/${jobId}`));
    last = j;
    const s = String(j?.status ?? '').toLowerCase();
    if (isTerminalSuccess(s)) return j;
    if (/fail|error|cancel/.test(s)) throw new Error(`job failed with status ${j?.status}`);
    await sleep(interval);
  }
  throw new Error(`timeout waiting for terminal job; last=${JSON.stringify(last)}`);
}
function assertJul252Unstarted(state, builds, jobs) {
  function check(obj) {
    if (!obj || typeof obj !== 'object') return;
    if (Array.isArray(obj)) { obj.forEach(check); return; }
    if (JSON.stringify(obj).includes('JUL-252')) {
      for (const k of ['status', 'state', 'phase']) {
        if (obj[k] != null) assert(!activeStatus(obj[k]), `JUL-252 is active: ${obj[k]}`);
      }
    }
    for (const v of Object.values(obj)) check(v);
  }
  check(state);
  check(builds);
  const arr = Array.isArray(jobs) ? jobs : (jobs?.jobs || []);
  for (const j of arr) {
    if (JSON.stringify(j).includes('JUL-252')) {
      assert(!activeStatus(j?.status), `JUL-252 job is active: ${j?.status}`);
    }
  }
}

try {
  const sourceCommit = (await execFileAsync('git', ['-C', ROOT, 'rev-parse', 'HEAD'])).stdout.toString().trim();
  const diffBuffer = (await execFileAsync('git', ['-C', ROOT, 'diff'], { encoding: 'buffer', maxBuffer: 100 * 1024 * 1024 })).stdout;
  const dirtyDigest = crypto.createHash('sha256').update(diffBuffer).digest('hex');
  evidence.source = { commit: sourceCommit, dirtyDigest };

  const state = await fetchJson(controlUrl('/api/state'));
  await writeFile(path.join(OUT, 'control-state-initial.json'), JSON.stringify(state, null, 2));
  const readyCards = findReadyCardArray(state);
  assert(readyCards, 'ready card list not found');
  const cardIndex = readyCards.findIndex(c => JSON.stringify(c).includes('JUL-232'));
  assert(cardIndex >= 0, 'JUL-232 ready card not found');
  const beamOffer = findBeamOffer(state);
  assert(beamOffer, 'Beam model offer not found');
  const beamValue = modelValue(beamOffer);
  assert(/beam/i.test(beamValue), `Beam value does not look like Beam: ${beamValue}`);
  evidence.readyCardIndex = cardIndex;
  evidence.beamValue = beamValue;

  browser = await chromium.launch({ headless: true });
  const context = await browser.newContext();
  const page = await context.newPage();
  page.on('request', req => evidence.network.requests.push({ url: req.url(), method: req.method(), time: new Date().toISOString() }));
  page.on('response', res => evidence.network.responses.push({ url: res.url(), status: res.status(), time: new Date().toISOString() }));
  page.on('requestfailed', req => evidence.network.failed.push({ url: req.url(), failure: req.failure()?.errorText || null, time: new Date().toISOString() }));
  page.on('console', msg => evidence.network.console.push({ type: msg.type(), text: msg.text(), time: new Date().toISOString() }));

  await page.goto(controlUrl(''), { waitUntil: 'networkidle' });
  const browserState = await page.evaluate(async (url) => {
    const r = await fetch(`${url}/api/state`);
    return { status: r.status, body: await r.json() };
  }, controlUrl(''));
  const browserBuilds = await page.evaluate(async (url) => {
    const r = await fetch(`${url}/api/builds`);
    return { status: r.status, body: await r.json() };
  }, controlUrl(''));
  await writeFile(path.join(OUT, 'browser-state.json'), JSON.stringify(browserState, null, 2));
  await writeFile(path.join(OUT, 'browser-builds.json'), JSON.stringify(browserBuilds, null, 2));

  await page.getByLabel(/Ready card/i).selectOption({ label: /JUL-232/ });
  await page.getByLabel(/Orchestrator route\/model/i).selectOption(beamValue);
  await page.getByLabel(/Coder route\/model/i).selectOption(beamValue);

  const startResponsePromise = page.waitForResponse(r => r.url().includes('/api/start') && r.request().method() === 'POST', { timeout: 60000 });
  await page.getByRole('button', { name: /Start/i }).click();
  const startResponse = await startResponsePromise;
  assert(startResponse.ok(), `Start API failed: ${startResponse.status()}`);
  const startBody = await startResponse.json();
  await writeFile(path.join(OUT, 'start-response.json'), JSON.stringify(startBody, null, 2));
  const savedJob = startBody?.build ?? startBody?.job ?? startBody;
  assert(savedJob && typeof savedJob === 'object', 'saved build missing from Start response');
  lastJob = savedJob;

  const jobId = savedJob?.id ?? savedJob?.jobId ?? savedJob?.job_id ?? savedJob?.runId ?? savedJob?.buildId;
  let job = await waitForJob(jobId, savedJob, 120000);
  lastJob = job;
  job = await waitForStatus(job.id ?? jobId, s => /run/i.test(s), 120000, 1000);
  lastJob = job;

  const runnerPid = job.runnerPid ?? job.runner_pid;
  const workerPid = job.workerPid ?? job.worker_pid;
  assert(Number.isInteger(runnerPid), 'runnerPid missing');
  const runnerStart = await procStart(runnerPid);
  const workerStart = workerPid ? await procStart(workerPid) : null;
  assert(await alive(runnerPid), 'runner PID not alive before restart');
  if (workerPid) assert(await alive(workerPid), 'worker PID not alive before restart');
  evidence.processIdentities.beforeRestart = { runnerPid, runnerStart, workerPid, workerStart, jobStatus: job.status };
  await writeFile(path.join(OUT, 'process-identities.json'), JSON.stringify(evidence.processIdentities, null, 2));

  const restartStart = new Date().toISOString();
  await execFileAsync('systemctl', ['--user', 'restart', CONTROL_USER_UNIT], { timeout: 180000 });
  const restartEnd = new Date().toISOString();
  await waitForControlState(60000);

  const jobAfterRestart = await fetchJson(runnerUrl(`/jobs/${job.id ?? jobId}`));
  lastJob = jobAfterRestart;
  assert(await alive(runnerPid), 'runner PID died during control restart');
  assert((await procStart(runnerPid)) === runnerStart, 'runner start identity changed');
  let completedDuringRestart = false;
  if (workerPid) {
    if (await alive(workerPid)) {
      assert((await procStart(workerPid)) === workerStart, 'worker start identity changed');
    } else if (isTerminalSuccess(jobAfterRestart.status)) {
      completedDuringRestart = true;
    } else {
      throw new Error(`worker ${workerPid} died during restart without successful completion`);
    }
  }
  const failedDuringRestart = evidence.network.failed.filter(f => f.time >= restartStart && f.time <= restartEnd);
  evidence.restart = {
    start: restartStart,
    end: restartEnd,
    completedDuringRestart,
    failedRequests: failedDuringRestart
  };
  await writeFile(path.join(OUT, 'restart.json'), JSON.stringify(evidence.restart, null, 2));

  const finalJob = await waitForTerminal(job.id ?? jobId, 15 * 60 * 1000, 1000);
  lastJob = finalJob;
  assert(isTerminalSuccess(finalJob.status), `job did not succeed: ${finalJob.status}`);
  assert(String(finalJob.status).toLowerCase().includes('ready'), `job not ready-for-review: ${finalJob.status}`);

  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForSelector('pre[data-testid="saved-build-result"]', { timeout: 60000 });
  const savedResultText = await page.locator('pre[data-testid="saved-build-result"]').textContent();
  const pageText = await page.locator('body').innerText();
  await writeFile(path.join(OUT, 'page-text.txt'), pageText);
  await page.screenshot({ path: path.join(OUT, 'screenshot.png'), fullPage: true });
  assert(savedResultText && savedResultText.includes('ready-for-review'), 'saved build result not ready-for-review');
  assert(savedResultText.includes(finalJob.candidateCommit), 'saved candidate string mismatch');

  assert.deepStrictEqual(savedJob.card, finalJob.card, 'saved card differs from actual result');
  assert.deepStrictEqual(savedJob.roles, finalJob.roles, 'saved roles differ from actual result');
  assert.equal(savedJob.worktree, finalJob.worktree, 'saved worktree differs from actual result');

  const jobDir = path.dirname(finalJob.worktree);
  const settings = JSON.parse(await readFile(path.join(jobDir, 'settings.json'), 'utf8'));
  const eventsRaw = await readFile(path.join(jobDir, 'events.jsonl'), 'utf8');
  const requestsRaw = await readFile(path.join(jobDir, 'requests.jsonl'), 'utf8');
  const ledger = JSON.parse(await readFile(path.join(jobDir, 'ledger.json'), 'utf8'));
  const events = eventsRaw.trim() ? eventsRaw.trim().split(/\n/).map(line => { try { return JSON.parse(line); } catch { return { raw: line }; } }) : [];
  const requests = requestsRaw.trim() ? requestsRaw.trim().split(/\n/).map(line => { try { return JSON.parse(line); } catch { return { raw: line }; } }) : [];

  for (const role of ['orchestrator', 'coder']) {
    const fullId = actualModel(finalJob, role);
    assert(typeof fullId === 'string' && fullId.length > 0, `actual model missing for ${role}`);
    const wire = settings?.models?.[fullId]?.wireModel;
    const savedId = savedRoles(savedJob)?.[role]?.modelId;
    assert.equal(wire, savedId, `${role} wireModel does not match saved modelId`);
    assert(/beam:free/i.test(String(wire)), `${role} is not Beam`);
    assert(events.some(e => JSON.stringify(e).includes(fullId)), `${role} start model ID not found in stock events`);
  }

  const successfulModelRequests = requests.filter(r => {
    const status = r?.status ?? r?.statusCode ?? r?.responseStatus ?? r?.httpStatus;
    const ok = typeof status === 'number' && status >= 200 && status < 300;
    const s = JSON.stringify(r).toLowerCase();
    const modelish = s.includes('chat') || s.includes('completion') || r?.model != null || String(r?.url || '').includes('model');
    return ok && modelish;
  });
  for (const r of successfulModelRequests) {
    assert(JSON.stringify(r).includes('reflection/beam:free'), 'successful model request is not reflection/beam:free');
  }
  const deepseekRequests = requests.filter(r => JSON.stringify(r).toLowerCase().includes('deepseek'));
  assert(deepseekRequests.length > 0, 'named DeepSeek refusal request not found');
  for (const r of deepseekRequests) {
    assert(JSON.stringify(r).includes('Trial forbids nonzero model prices'), 'DeepSeek refusal text missing');
    const status = r?.status ?? r?.statusCode ?? r?.responseStatus ?? r?.httpStatus;
    assert(status == null || status === 0 || status === 'refused' || (typeof status === 'number' && status >= 400), 'DeepSeek request was dispatched with a success status');
  }
  const deepseekSubagentEvents = events.filter(e => {
    const s = JSON.stringify(e).toLowerCase();
    return s.includes('deepseek') && /subagent_(start|end)/.test(s);
  });
  assert(deepseekSubagentEvents.length >= 2, 'DeepSeek subagent start/end events missing');
  for (const e of deepseekSubagentEvents) {
    const s = JSON.stringify(e);
    assert(s.includes('cap-check'), 'DeepSeek subagent event is not cap-check');
    assert(/"isError"\s*:\s*true/i.test(s), 'DeepSeek subagent event isError is not true');
  }

  assert(finalJob.account, 'worker account missing');
  assert.equal(finalJob.account.spentNano, 0, 'spentNano is not zero');
  assert.equal(finalJob.account.heldNano, 0, 'heldNano is not zero');
  assert(typeof finalJob.threadId === 'string' && finalJob.threadId.length > 0, 'threadId missing');
  assert(finalJob.internalReview, 'internalReview missing');
  assert(Array.isArray(finalJob.internalReview.starts), 'internalReview starts missing');
  assert(Array.isArray(finalJob.internalReview.ends), 'internalReview ends missing');
  assert(Array.isArray(finalJob.internalReview.events), 'internalReview events missing');
  assert(finalJob.deepseekRefusal === true || String(finalJob.deepseekRefusal).toLowerCase() === 'true' || finalJob.deepseekRefusal != null, 'deepseekRefusal missing');
  assert(finalJob.deepseekSent === false || String(finalJob.deepseekSent).toLowerCase() === 'false', 'deepseekSent is not false');
  assert(finalJob.downstreamReviewStarted === false, 'downstream review was started');

  const spent = ledger.spentNano ?? ledger.account?.spentNano;
  const held = ledger.heldNano ?? ledger.account?.heldNano;
  assert.equal(spent, 0, 'ledger spentNano is not zero');
  assert.equal(held, 0, 'ledger heldNano is not zero');

  const worktree = finalJob.worktree;
  const baseCommit = finalJob.baseCommit;
  const candidateCommit = finalJob.candidateCommit;
  assert(baseCommit && candidateCommit && baseCommit !== candidateCommit, 'invalid commit range');
  assert(baseCommit !== sourceCommit, 'saved run does not have an independent base');
  const markerBuffer = (await execFileAsync('git', ['-C', worktree, 'show', `${candidateCommit}:BUILD-PHASE-REHEARSAL.txt`], { encoding: 'buffer', maxBuffer: 100 * 1024 * 1024 })).stdout;
  assert.deepEqual(markerBuffer, MARKER, 'candidate marker bytes mismatch');
  const diffNames = (await execFileAsync('git', ['-C', worktree, 'diff', '--name-only', baseCommit, candidateCommit])).stdout.toString().trim().split(/\n/).filter(Boolean);
  assert.deepEqual(diffNames, ['BUILD-PHASE-REHEARSAL.txt'], 'candidate diff is not solely BUILD-PHASE-REHEARSAL.txt');
  const statusOut = (await execFileAsync('git', ['-C', worktree, 'status', '--porcelain'])).stdout.toString().trim();
  assert.equal(statusOut, '', 'worktree is not clean');

  const requiredFiles = ['settings.json', 'events.jsonl', 'requests.jsonl', 'ledger.json', 'receipt.json', 'job.json'];
  for (const f of requiredFiles) {
    await stat(path.join(jobDir, f));
    await copyFile(path.join(jobDir, f), path.join(OUT, 'job-files', f));
  }

  const finalState = await fetchJson(controlUrl('/api/state'));
  const finalBuilds = await fetchJson(controlUrl('/api/builds')).catch(() => null);
  const runnerJobs = await fetchJson(runnerUrl('/jobs')).catch(() => null);
  assertJul252Unstarted(finalState, finalBuilds, runnerJobs);

  evidence.jobId = finalJob.id ?? jobId;
  evidence.finalStatus = finalJob.status;
  evidence.cardIndex = cardIndex;
  evidence.beamValue = beamValue;
  evidence.savedResultText = savedResultText;
  evidence.processIdentities.afterRestart = {
    runnerPid,
    runnerStart,
    workerPid,
    workerStart,
    completedDuringRestart,
    finalRunnerAlive: await alive(runnerPid)
  };
  evidence.git = { sourceCommit, dirtyDigest, baseCommit, candidateCommit, diffNames, marker: MARKER.toString() };
  evidence.filesCopied = requiredFiles;
  evidence.pass = true;
  evidence.finishedAt = new Date().toISOString();

  await writeFile(path.join(OUT, 'network.json'), JSON.stringify(evidence.network, null, 2));
  await writeFile(path.join(OUT, 'report.json'), JSON.stringify(evidence, null, 2));
} catch (err) {
  evidence.pass = false;
  evidence.error = err?.stack || String(err);
  evidence.finishedAt = new Date().toISOString();
  if (lastJob) {
    evidence.lastJob = lastJob;
    try { await writeFile(path.join(OUT, 'last-job.json'), JSON.stringify(lastJob, null, 2)); } catch {}
  }
  try { await writeFile(path.join(OUT, 'network.json'), JSON.stringify(evidence.network, null, 2)); } catch {}
  try { await writeFile(path.join(OUT, 'report.json'), JSON.stringify(evidence, null, 2)); } catch {}
  throw err;
} finally {
  if (browser) await browser.close();
}
